import 'server-only'

type PageViewEvent = {
  path: string
  title: string
  occurredAt: string
}

export async function logPageView(event: PageViewEvent) {
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    console.info('analytics.page_view', event)
    return
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      event: 'page_view',
      ...event,
    }),
    cache: 'no-store',
  })

  if (!response.ok) {
    throw new Error(`Analytics request failed with ${response.status}`)
  }
}

