import { after, connection } from 'next/server'
import { logPageView } from './analytics'

export default async function Home() {
  await connection()

  const pageView = {
    path: '/',
    title: 'Welcome Page',
    occurredAt: new Date().toISOString(),
  }

  after(async () => {
    try {
      await logPageView(pageView)
    } catch (error) {
      console.error('Failed to log page view', error)
    }
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting. Your page view is being recorded.</p>
    </main>
  )
}

